using System;
using System.Linq;
using System.Drawing;
using System.Drawing.Imaging;
using System.Runtime.InteropServices;
using System.Text.RegularExpressions;
using System.Threading.Tasks;
using Windows.Media.Ocr;
using Windows.Graphics.Imaging;
using Windows.Storage.Streams;
internal sealed class SongesObservation {internal bool EndTurn,Victory,Defeat;internal int? Depth;internal string DepthText;}
internal sealed class SongesOcr {
 OcrEngine engine;
 internal SongesOcr(){engine=OcrEngine.TryCreateFromLanguage(new Windows.Globalization.Language("fr-FR"))??OcrEngine.TryCreateFromUserProfileLanguages();if(engine==null)throw new InvalidOperationException("Reconnaissance de texte Windows indisponible. Installez le composant OCR français dans les options de langue Windows, puis relancez. Le chrono manuel reste utilisable.");}
 static async Task<T> Await<T>(Windows.Foundation.IAsyncOperation<T> operation){return await Task.Run(delegate{try{var until=DateTime.UtcNow.AddSeconds(8);while(operation.Status==Windows.Foundation.AsyncStatus.Started){if(DateTime.UtcNow>until){operation.Cancel();throw new TimeoutException("La lecture d’écran met trop de temps à répondre.");}System.Threading.Thread.Sleep(20);}if(operation.Status!=Windows.Foundation.AsyncStatus.Completed)throw new InvalidOperationException("Lecture d’écran impossible.",operation.ErrorCode);return operation.GetResults();}finally{operation.Close();}});}
 internal static int? Depth(string text){var m=Regex.Match(text??"",@"\bProfo[a-z]{3,8}\s*[:·•-]?\s*([0-9SOso]{1,2})\b",RegexOptions.IgnoreCase);int value;return m.Success&&Int32.TryParse(m.Groups[1].Value.Replace("S","5").Replace("s","5").Replace("O","0").Replace("o","0"),out value)&&value<=25?(int?)value:null;}
 internal async Task<SongesObservation> Read(Bitmap frame){var result=new SongesObservation();string top=await ReadText(frame,new Rectangle(0,0,Math.Min(frame.Width,700),Math.Min(frame.Height,190)),2);result.DepthText=top;result.Depth=Depth(top);int left=(int)(frame.Width*.25),start=(int)(frame.Height*.52);var region=new Rectangle(left,start,(int)(frame.Width*.65),frame.Height-start);var lines=await ReadLines(frame,region,1.8);foreach(var line in lines.Lines){string text=Regex.Replace(line.Text.ToUpperInvariant(),@"\s+"," ");double x=region.Left+line.Words.Min(w=>w.BoundingRect.X)/lines.Scale,y=region.Top+line.Words.Min(w=>w.BoundingRect.Y)/lines.Scale;if(Word(text,"FINDETOUR")&&x>frame.Width*.45&&y>frame.Height*.75)result.EndTurn=true;if(Word(text,"VICTOIRE")&&GoldNear(frame,(int)x,(int)y))result.Victory=true;if(Regex.IsMatch(text,@"\bD[ÉE]FAITE\b")&&x>frame.Width*.3&&y>frame.Height*.55)result.Defeat=true;}return result;}
 internal static bool Word(string text,string target){string compact=Regex.Replace((text??"").ToUpperInvariant().Replace('É','E').Replace('0','O'),"[^A-Z]","");if(compact.Contains(target))return true;for(int length=Math.Max(1,target.Length-1);length<=target.Length+1;length++)for(int start=0;start+length<=compact.Length;start++){string candidate=compact.Substring(start,length);int i=0,j=0,errors=0;while(i<candidate.Length&&j<target.Length){if(candidate[i]==target[j]){i++;j++;continue;}if(++errors>1)break;if(candidate.Length>=target.Length)i++;if(candidate.Length<=target.Length)j++;}errors+=candidate.Length-i+target.Length-j;if(errors<=1)return true;}return false;}
 static bool GoldNear(Bitmap bitmap,int x,int y){int count=0;for(int yy=Math.Max(0,y-8);yy<Math.Min(bitmap.Height,y+30);yy+=3)for(int xx=Math.Max(0,x-45);xx<Math.Min(bitmap.Width,x+180);xx+=3){var c=bitmap.GetPixel(xx,yy);if(c.R>140&&c.G>100&&c.B<c.G*.65)count++;}return count>18;}
 sealed class OcrLines {internal System.Collections.Generic.IReadOnlyList<OcrLine> LinesList;internal System.Collections.Generic.IReadOnlyList<OcrLine> Lines {get{return LinesList;}}internal double Scale;}
 async Task<OcrLines> ReadLines(Bitmap frame,Rectangle rect,double wanted,int whiteThreshold=175){double scale=Math.Min(wanted,Math.Min((double)OcrEngine.MaxImageDimension/rect.Width,(double)OcrEngine.MaxImageDimension/rect.Height));int width=(int)(rect.Width*scale),height=(int)(rect.Height*scale);using(var cropped=new Bitmap(width,height,PixelFormat.Format32bppArgb)){using(var g=Graphics.FromImage(cropped)){g.InterpolationMode=System.Drawing.Drawing2D.InterpolationMode.HighQualityBicubic;g.DrawImage(frame,new Rectangle(0,0,width,height),rect,GraphicsUnit.Pixel);}var pixels=new byte[width*height*4];var data=cropped.LockBits(new Rectangle(0,0,width,height),ImageLockMode.ReadOnly,PixelFormat.Format32bppArgb);try{for(int y=0;y<height;y++)Marshal.Copy(IntPtr.Add(data.Scan0,y*data.Stride),pixels,y*width*4,width*4);}finally{cropped.UnlockBits(data);}for(int i=0;i<pixels.Length;i+=4){byte value=pixels[i]>whiteThreshold&&pixels[i+1]>whiteThreshold&&pixels[i+2]>whiteThreshold?(byte)0:(byte)255;pixels[i]=pixels[i+1]=pixels[i+2]=value;pixels[i+3]=255;}using(var writer=new DataWriter()){writer.WriteBytes(pixels);using(var bitmap=SoftwareBitmap.CreateCopyFromBuffer(writer.DetachBuffer(),BitmapPixelFormat.Bgra8,width,height,BitmapAlphaMode.Ignore)){var result=await Await(engine.RecognizeAsync(bitmap));return new OcrLines{LinesList=result.Lines,Scale=scale};}}}}
 async Task<string> ReadText(Bitmap frame,Rectangle rect,double scale){var result=await ReadLines(frame,rect,3,120);return String.Join("\n",result.Lines.Select(l=>l.Text));}
}
